{
  "implementation": "def solve(case):
    lines = case.get('lines', [])
    trajectory = []
    expected = {'thought', 'final'}
    error_line = None
    i = 0
    while i < len(lines):
        line = lines[i]
        parts = line.split(': ', 1)
        if len(parts) != 2:
            error_line = i + 1
            break
        prefix, content = parts
        type_map = {
            'Thought': 'thought',
            'Action': 'action',
            'Observation': 'observation',
            'Final': 'final'
        }
        if prefix not in type_map:
            error_line = i + 1
            break
        tp = type_map[prefix]
        if tp not in expected:
            error_line = i + 1
            break
        if tp == 'final' and i != len(lines) - 1:
            error_line = i + 1
            break
        trajectory.append({'type': tp, 'content': content})
        if tp == 'thought':
            expected = {'action'}
        elif tp == 'action':
            expected = {'observation'}
        elif tp == 'observation':
            expected = {'thought', 'final'}
        elif tp == 'final':
            expected = set()
        i += 1
    else:
        if trajectory and trajectory[-1]['type'] != 'final':
            error_line = len(lines)
            trajectory.pop()
    valid = error_line is None
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}"
}
